def transform(grid):
    h, w = len(grid), len(grid[0])

    # A horizontal divider separates aligned upper and lower panels.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            upper, lower = grid[:r], grid[r + 1:]
            return [
                [3 if upper[i][j] != 2 and lower[i][j] == 5 else 5
                 for j in range(w)]
                for i in range(len(upper))
            ]

    # A vertical divider separates aligned left and right panels.
    c = next(j for j in range(w) if all(row[j] == grid[0][j] for row in grid))
    left, right = [row[:c] for row in grid], [row[c + 1:] for row in grid]
    bg = max(set(v for row in left for v in row),
             key=lambda v: sum(row.count(v) for row in left))
    marker = next(v for row in right for v in row if v != 8)
    return [
        [3 if left[i][j] != bg and right[i][j] == marker else 8
         for j in range(c)]
        for i in range(h)
    ]
